{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service = 'invoice-agent'",
      "why": "Check invoice-agent disk usage since it is the only service with 'disk quota exceeded' errors not yet checked, and it is a dependency of worker."
    }
  ],
  "hypotheses": [
    {
      "service": "invoice-agent",
      "kind": "resource_exhaustion",
      "mechanism": "Invoice-agent exhausted its disk quota, causing invoice file write failures that propagate to worker message processing.",
      "supporting": ["E14", "E15", "E6", "E9", "E12", "E13", "E11"],
      "refuting": ["E19"],
      "explains": ["I2_no_orphaned_orders", "E3", "E5", "E6", "E8", "E9", "E10", "E11", "E12", "E13", "E14", "E15"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "invoice-agent"}}
      ]
    },
    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "Sync-job exhausted its disk quota, causing ledger export write failures and sync errors.",
      "supporting": ["E16", "E4", "E7"],
      "refuting": ["E21", "E32"],
      "explains": ["E4", "E7", "E16"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    }
  ],
  "summary": "Disk quota exhaustion in invoice-agent is the primary cause, with sync-job also affected independently."
}
